 "mainEntity": [
  {
   "@type": "Question",
   "name": "Why do dogs want to poop on leaves?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "It's commonly explained that leaf piles hold other dogs' scents for a long time, they're soft enough to squat on comfortably, and poop doesn't get on paws. Some dogs also seek out the feel of the ground they got used to as puppies."
   }
  },
  {
   "@type": "Question",
   "name": "Why do dogs circle before pooping?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "It's known as a way of choosing a spot and checking the surroundings. One study found dogs line up north–south when conditions are calm, but not every dog does this."
   }
  },
  {
   "@type": "Question",
   "name": "Is it okay to let my dog poop on leaves?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "Yes. But leaf piles can hide ticks, chestnut burrs, broken glass, mushrooms and other animals' droppings, so check your dog's paws and body after the walk."
   }
  },
  {
   "@type": "Question",
   "name": "How do I pick up poop on leaves?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "Double up two bags over your hand and scoop it up leaves and all for a clean pickup. A grabber or a portable scoop makes it even easier."
   }
  }
 ]
